115	    async fn list_snapshots(&self, directory: &Path) -> CollectionResult<Vec<SnapshotDescription>> {
116	        let mut entries = tokio::fs::read_dir(directory).await?;
117	        let mut snapshots = Vec::new();
118	
119	        while let Some(entry) = entries.next_entry().await? {
120	            let path = entry.path();
121	
122	            if !path.is_dir() && path.extension().map_or(false, |ext| ext == "snapshot") {
123	                snapshots.push(get_snapshot_description(&path).await?);
124	            }
125	        }
126	
