130	    async fn store_file(
131	        &self,
132	        source_path: &Path,
133	        target_path: &Path,
134	    ) -> CollectionResult<SnapshotDescription> {
135	        // Steps:
136	        //
137	        // 1. Make sure that the target directory exists.
138	        // 2. Compute the checksum of the source file.
139	        // 3. Generate temporary file name, which should be used on the same file system as the target directory.
140	        // 4. Move or copy the source file to the temporary file. (move might not be possible if the source and target are on different file systems)
141	        // 5. Move the temporary file to the target file. (move is atomic, copy is not)
142	
143	        if let Some(target_dir) = target_path.parent() {
144	            if !target_dir.exists() {
145	                std::fs::create_dir_all(target_dir)?;
146	            }
147	        }
148	
149	        // Move snapshot to permanent location.
150	        // We can't move right away, because snapshot folder can be on another mounting point.
151	        // We can't copy to the target location directly, because copy is not atomic.
152	        // So we copy to the final location with a temporary name and then rename atomically.
153	        let target_path_tmp_move = target_path.with_extension("tmp");
154	        // Ensure that the temporary file is deleted on error
155	        let _temp_path = TempPath::from_path(&target_path_tmp_move);
156	
157	        // compute and store the file's checksum before the final snapshot file is saved
158	        // to avoid making snapshot available without checksum
159	        let checksum_path = get_checksum_path(target_path);
160	        let checksum = hash_file(source_path).await?;
161	        let checksum_file = TempPath::from_path(&checksum_path);
162	        let mut file = tokio::fs::File::create(checksum_path.as_path()).await?;
163	        file.write_all(checksum.as_bytes()).await?;
164	
165	        if target_path != source_path {
166	            move_file(&source_path, &target_path_tmp_move).await?;
167	            tokio::fs::rename(&target_path_tmp_move, &target_path).await?;
168	        }
169	
170	        checksum_file.keep()?;
171	        get_snapshot_description(target_path).await
172	    }
